"""Fixed BY2 first50-epoch source diagnostic; inputs and output paths are supplied by --config."""
from pathlib import Path
import sys,json,hashlib,time,math,collections,argparse
import numpy as np
from scipy import sparse,linalg
parser=argparse.ArgumentParser();parser.add_argument('--config',type=Path,required=True);args=parser.parse_args();config=json.loads(args.config.read_text());R=Path(config['repository']);sys.path.insert(0,str(R/'src'))
from legsa_gins.paper_rebuild.carrier_phase.temporal import EpochBlock,assemble_epochs
from legsa_gins.paper_rebuild.joint_navigation.carrier_relations import analyze_relation_transition,reparameterize_epoch_blocks
OUT=Path(config['output_directory']);OUT.mkdir(parents=True,exist_ok=True);start=time.monotonic();P=Path(config['plan_path']);plan=json.loads(P.read_text());records=[v for v in plan['records'] if 100.1979<=v['time_s']<=110.0];assert len(records)==50;blocks=[];sources=[]
for rec in records:
 f=rec['families']['GPS_GAL_BDS_DUAL'];assert f['status']=='BUILT';path=P.parent/f['file'];z=np.load(path);blocks.append(EpochBlock(rec['time_s'],z['y'],z['A'],z['B'],z['Q'],tuple(f['ambiguity_labels']),dict(f['metadata'])));sources.append({'time_s':rec['time_s'],'path':str(path),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'causal_navigation_cutoff_s':rec['navigation']['causal_cutoff_relative_s']})
physical=reparameterize_epoch_blocks(blocks,label_mode='physical_sd_arcs',available_time_s=110.0);problem=assemble_epochs(physical.blocks,length_m=.35);offset=np.r_[0,np.cumsum([len(b.y) for b in blocks])];ds=[];rowmeta=[];phase_groups=[];transitions=[]
for k,b in enumerate(blocks):
 m=len(b.ambiguity_labels)
 for j in range(m):
  row={int(offset[k]+j):1.};ds.append(row);target,_,pivot,_=json.loads(b.ambiguity_labels[j]);parts=target.split(':');rowmeta.append({'kind':'code','epoch_index':k,'time_s':b.time_s,'group':':'.join([parts[0],parts[2],parts[3]]),'target':target,'pivot':pivot})
code_count=len(ds)
for k in range(1,len(blocks)):
 prev,cur=blocks[k-1],blocks[k];tr=analyze_relation_transition(prev.ambiguity_labels,cur.ambiguity_labels,label_mode='physical_sd_arcs');transitions.append({'time_s':cur.time_s,'previous_time_s':prev.time_s,'intersection_rank':tr.intersection_rank,'current_rank':tr.current_relation_rank,'history_rank':tr.history_relation_rank,'status':tr.continuation_status});mp,mc=len(prev.ambiguity_labels),len(cur.ambiguity_labels)
 for crow,hrow,basis in zip(tr.current_transform,tr.history_transform,tr.intersection_basis):
  nodes=[(tr.nodes[j],int(v)) for j,v in enumerate(basis) if v];sign=1 if nodes[0][1]>0 else -1;nodes=[(n,sign*v) for n,v in nodes];groups={':'.join([n[1].split(':')[0],n[1].split(':')[2],n[1].split(':')[3]]) for n,_ in nodes};assert len(groups)==1;group=groups.pop();row={}
  for j,v in enumerate(crow):
   if v:row[int(offset[k]+mc+j)]=float(sign*v)
  for j,v in enumerate(hrow):
   if v:row[int(offset[k-1]+mp+j)]=-float(sign*v)
  wavelengths=[cur.A[mc+j,j] for j,v in enumerate(crow) if v]+[prev.A[mp+j,j] for j,v in enumerate(hrow) if v];assert np.ptp(wavelengths)<1e-14
  rel=json.dumps(nodes,separators=(',',':'));ds.append(row);rowmeta.append({'kind':'phase_time_difference','epoch_index':k,'time_s':cur.time_s,'previous_time_s':prev.time_s,'group':group,'relation_id':rel,'physical_sd_incidence':nodes,'wavelength_m':float(wavelengths[0])})
data=[];ri=[];ci=[]
for i,row in enumerate(ds):
 for j,v in row.items():ri.append(i);ci.append(j);data.append(v)
D=sparse.csr_matrix((data,(ri,ci)),shape=(len(ds),len(problem.y)));Qraw=sparse.block_diag([b.Q for b in blocks],format='csr');Q=(D@Qraw@D.T).toarray();y=np.asarray(D@problem.y);B=np.asarray(D@problem.B);integer_cancel=np.asarray(D@problem.A);maxcancel=float(np.max(abs(integer_cancel)));assert maxcancel<1e-13
L=linalg.cholesky(Q,lower=True);yw=linalg.solve_triangular(L,y,lower=True);bw=linalg.solve_triangular(L,B,lower=True);u,rr=linalg.qr(bw,mode='economic');rank=int(np.linalg.matrix_rank(rr));assert rank==3*len(blocks);fit=linalg.solve_triangular(rr,u.T@yw);rw=yw-u@(u.T@yw);res=y-B@fit;lu=L@u;Rres=Q-lu@lu.T;Rres=(Rres+Rres.T)/2;variances=np.diag(Rres);std=np.sqrt(variances);corr=Rres/std[:,None]/std[None,:];rz=res/std;totalcost=float(rw@rw);df=len(y)-rank
print('MODEL',len(problem.y),problem.ambiguity_count,'DIFFERENCES',len(y)-code_count,'rows',len(y),'baseline_rank',rank,'max_integer_cancel',maxcancel,'cost',totalcost,'df',df,flush=True)
group_results=[]
for group in sorted({r['group'] for r in rowmeta}):
 ix=np.array([i for i,r in enumerate(rowmeta) if r['kind']=='phase_time_difference' and r['group']==group]);q=Q[np.ix_(ix,ix)];r=Rres[np.ix_(ix,ix)];v=res[ix];factor=linalg.cho_factor(q,lower=True);cost=float(v@linalg.cho_solve(factor,v));expected=float(np.trace(linalg.cho_solve(factor,r)));group_results.append({'group':group,'phase_difference_rows':len(ix),'full_temporal_Q_residual_cost':cost,'null_expected_cost_after_baseline_fit':expected,'cost_over_null_expectation':cost/expected,'raw_phase_difference_residual_rms_m':float(np.sqrt(np.mean(v*v))),'residual_covariance_expected_rms_m':float(np.sqrt(np.mean(np.diag(r))))})
codeix=np.arange(code_count);qc=Q[np.ix_(codeix,codeix)];rc=Rres[np.ix_(codeix,codeix)];fc=linalg.cho_factor(qc,lower=True);codecost=float(res[codeix]@linalg.cho_solve(fc,res[codeix]));codeexpected=float(np.trace(linalg.cho_solve(fc,rc)))
lookup={(r['relation_id'],r['epoch_index']):i for i,r in enumerate(rowmeta) if r['kind']=='phase_time_difference'};scores=[]
for lag in (1,2,3):
 pairs=[(i,lookup[r['relation_id'],r['epoch_index']+lag]) for i,r in enumerate(rowmeta) if r['kind']=='phase_time_difference' and (r['relation_id'],r['epoch_index']+lag) in lookup];aa=np.array([a for a,b in pairs]);bb=np.array([b for a,b in pairs]);observed=float(np.sum(rz[aa]*rz[bb]));expected=float(np.sum(corr[aa,bb]));variance=float(np.sum(corr[np.ix_(aa,aa)]*corr[np.ix_(bb,bb)]+corr[np.ix_(aa,bb)]*corr[np.ix_(bb,aa)]));assert variance>0;scores.append({'lag_intervals':lag,'nominal_lag_s':.2*lag,'same_physical_relation_pairs':len(pairs),'observed_standardized_product_sum':observed,'expected_product_sum_under_original_Q_and_baseline_projection':expected,'observed_minus_expected':observed-expected,'exact_gaussian_null_standard_deviation':math.sqrt(variance),'standardized_excess_descriptive_not_normal_pvalue':(observed-expected)/math.sqrt(variance),'observed_product_mean':observed/len(pairs),'expected_product_mean':expected/len(pairs)})
# Additional adjacent-increment score by physical signal group, still using the full joint-fit covariance.
group_lag=[]
for group in sorted({r['group'] for r in rowmeta}):
 pairs=[(i,lookup[r['relation_id'],r['epoch_index']+1]) for i,r in enumerate(rowmeta) if r['kind']=='phase_time_difference' and r['group']==group and (r['relation_id'],r['epoch_index']+1) in lookup];aa=np.array([a for a,b in pairs]);bb=np.array([b for a,b in pairs]);observed=float(np.sum(rz[aa]*rz[bb]));expected=float(np.sum(corr[aa,bb]));variance=float(np.sum(corr[np.ix_(aa,aa)]*corr[np.ix_(bb,bb)]+corr[np.ix_(aa,bb)]*corr[np.ix_(bb,aa)]));group_lag.append({'group':group,'same_relation_pairs':len(pairs),'observed_product_mean':observed/len(pairs),'null_expected_product_mean':expected/len(pairs),'excess_over_null_sd':(observed-expected)/math.sqrt(variance)})
summary={'scope':{'sequence':'BY2','fixed_source_window_s':[100.19799995422363,110.0],'actual_first_last_s':[blocks[0].time_s,blocks[-1].time_s],'epochs':len(blocks),'raw_rows':len(problem.y),'raw_physical_forest_integer_dimension':problem.ambiguity_count,'code_rows_preserved':code_count,'same_arc_phase_difference_rows':len(y)-code_count,'joint_difference_rows':len(y),'free_baseline_rank':rank,'source_selection':'Every GPS_GAL_BDS_DUAL BUILT block in the fixed source-defined window, no error-based selection. Phase differences require exact surviving physical integer relations; no cross-slip continuity is invented.','reference_reads':0,'navigation_calls':0,'integer_search_calls':0,'best_integer_residuals_used':False,'Q_or_threshold_changes':False},'provenance':{'PLAN':str(P),'PLAN_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'source_blocks':sources,'analysis_script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'source_modules':[{'path':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in [R/'src/legsa_gins/paper_rebuild/joint_navigation/carrier_relations.py',R/'src/legsa_gins/paper_rebuild/carrier_phase/temporal.py']]},'method':{'model':'y=A*N+B*b+epsilon; adjacent physical relation maps obey C*N_current=H*N_previous. Preserve every code row and transform phase rows with C*y_current-H*y_previous.','integer_annihilation_max_abs_DA':maxcancel,'covariance':'Q_difference=D*Q_original*D.T; includes shared-pivot correlations and negative cross-time covariance from reused original phase packets. No diagonalization or independent-difference assumption.','baseline_projection':'One arbitrary3D baseline at each of50 epochs, generalized least squares against full transformed covariance; no constant-heading/rotation approximation across epochs.','residual_covariance':'R=Q_difference-B*(B.T*Q_difference^-1*B)^-1*B.T; all lag-null expectations include this projection.','lag_statistic':'For exact same physical relation and fixed lag, sum(r_i*r_j/sqrt(Rii*Rjj)). Null expectation=sum(Rij/sqrt(Rii*Rjj)); variance=sum_ab(C_ia,ib*C_ja,jb+C_ia,jb*C_ja,ib) via Isserlis. Standardized excess is a descriptive quadratic-score scale, not an independent-vote z-test or calibrated normal p-value.'},'joint_fit':{'cost':totalcost,'null_degrees_of_freedom':df,'cost_over_degrees_of_freedom':totalcost/df,'code_cost':codecost,'code_expected_cost':codeexpected,'phase_difference_cost':sum(v['full_temporal_Q_residual_cost'] for v in group_results),'phase_expected_cost_after_baseline_fit':sum(v['null_expected_cost_after_baseline_fit'] for v in group_results)},'phase_groups':group_results,'physical_same_relation_temporal_scores':scores,'lag1_group_descriptive_scores':group_lag,'limitations':['Time differences remove both any constant integer offset and any constant phase bias within surviving physical relations. They cannot identify the absolute phase-bias mean separately from N.','Any temporal pattern may include multipath/phase bias, RAWX precision-model error, Doppler/receiver synchronization effects, cached known_sd/ephemeris errors and geometry linearization. This diagnostic does not attribute it uniquely to beta.','The remaining geometric effect is outside the fitted per-epoch free-baseline columns; arbitrary common baseline changes are projected away, but this is not a nonlinear robot-state model.','Adjacent difference correlations and baseline-fit covariance are explicitly accounted for. Per-group and per-lag scores share observations and are not independent evidence.','No scale or correlation time is estimated for insertion into the navigation algorithm; no new model is qualified by making the old EMPTY domain nonempty.'],'elapsed_s':time.monotonic()-start}
(OUT/'SUMMARY.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n');(OUT/'ROWS_AND_TRANSITIONS.json').write_text(json.dumps({'rows':rowmeta,'transitions':transitions},indent=2,ensure_ascii=False)+'\n');np.savez_compressed(OUT/'DIFFERENCE_DIAGNOSTIC.npz',y=y,B=B,Q=Q,residual=res,residual_covariance=Rres,baseline_ecef_m=fit.reshape(-1,3),whitened_residual=rw,D_data=D.data,D_indices=D.indices,D_indptr=D.indptr,D_shape=np.array(D.shape));print('GROUPS',json.dumps(group_results),flush=True);print('LAGS',json.dumps(scores),flush=True);print('GROUP_LAG1',json.dumps(group_lag),flush=True);print('FINISHED',OUT,'elapsed',summary['elapsed_s'],flush=True)
